using System;using System.Linq;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace XuanwuTools { public static class MountainBackdropBuilder {
 [Serializable] class Config {public string scenePath, id, materialPath;public Vector3 position;public float width,depth,height;public int seed=17;}
 [MenuItem(Common.Menu+"09 Build backdrop mesh JSON")] public static void Build()=>Common.Run(()=>{var c=Common.Read<Config>();Common.SceneGuard(c.scenePath);if(string.IsNullOrEmpty(c.id)||c.id.Contains("/")||c.width<=0||c.depth<=0||c.height<=0||!Common.Finite(c.position))throw new Exception("Invalid backdrop config");string name="XuanwuGenerated_Backdrop_"+c.id;if(SceneManager.GetActiveScene().GetRootGameObjects().Any(o=>o.name==name))throw new Exception("Backdrop ID exists");var m=AssetDatabase.LoadAssetAtPath<Material>(c.materialPath);if(!m)throw new Exception("Assign existing compatible material");if(!Common.Confirm("Backdrop dry-run","Create low-resolution far mesh, no collider. Review position outside playable space."))return;const int n=33;var v=new Vector3[n*n];var uv=new Vector2[v.Length];var tri=new int[(n-1)*(n-1)*6];int k=0;for(int z=0;z<n;z++)for(int x=0;x<n;x++){float u=x/(float)(n-1),w=z/(float)(n-1);float envelope=Mathf.Sin(u*Mathf.PI)*Mathf.Sin(w*Mathf.PI);float ridge=Mathf.Pow(Mathf.PerlinNoise(u*5+c.seed,w*4),1.4f);v[z*n+x]=new Vector3((u-.5f)*c.width,envelope*ridge*c.height,(w-.5f)*c.depth);uv[z*n+x]=new Vector2(u,w);if(z<n-1&&x<n-1){int i=z*n+x;tri[k++]=i;tri[k++]=i+n;tri[k++]=i+1;tri[k++]=i+1;tri[k++]=i+n;tri[k++]=i+n+1;}}var mesh=new Mesh{name=name};mesh.vertices=v;mesh.uv=uv;mesh.triangles=tri;mesh.RecalculateNormals();mesh.RecalculateBounds();if(!AssetDatabase.IsValidFolder("Assets/XuanwuGenerated"))AssetDatabase.CreateFolder("Assets","XuanwuGenerated");AssetDatabase.CreateAsset(mesh,AssetDatabase.GenerateUniqueAssetPath("Assets/XuanwuGenerated/"+name+".asset"));var o=new GameObject(name);Undo.RegisterCreatedObjectUndo(o,"Create backdrop");o.transform.position=c.position;o.AddComponent<MeshFilter>().sharedMesh=mesh;o.AddComponent<MeshRenderer>().sharedMaterial=m;EditorSceneManager.MarkSceneDirty(o.scene);AssetDatabase.SaveAssetIfDirty(mesh);});}}
